<?php
namespace App\Http\Controllers;use App\Http\Requests\StoreTrainingTopicRequest;use App\Models\{TrainingAudit,TrainingTopic};class TrainingTopicController extends Controller{public function index(){$topics=TrainingTopic::availableTo(auth()->user()->company_id)->orderBy('name')->get();return view('training.topics.index',compact('topics'));}public function store(StoreTrainingTopicRequest$r){$d=$r->validated();foreach(['requires_evaluation_default','is_regulated','is_active']as$f)$d[$f]=$r->boolean($f);$topic=TrainingTopic::create(array_merge($d,['company_id'=>$r->user()->company_id,'created_by'=>$r->user()->id,'updated_by'=>$r->user()->id]));TrainingAudit::create(['company_id'=>$r->user()->company_id,'event'=>'training_topic_created','subject_type'=>'training_topic','subject_id'=>$topic->id,'user_id'=>$r->user()->id,'created_at'=>now()]);return back()->with('success','Tema creado en el catálogo.');}}
